    {
      "id": "F01",
      "name": "Core workflows perform real operations",
      "group": "F",
      "starts_at": "Essential",
      "purpose_and_user_impact": "Prevent users relying on an interface that only simulates a promised result.",
      "applicability": {
        "any_features": [],
        "applies_when": "Always assess the agreed core tasks.",
        "not_applicable_when": "No exclusion at criterion level; missing access or requirements means unknown."
      },
      "expected_behavior": "Each agreed essential task produces its actual intended result; any demo or mock behavior is disclosed.",
      "test_steps": [
        "List core tasks and their acceptance outcomes from the agreed requirements.",
        "Execute each task end to end using a unique test marker.",
        "Read the resulting artifact or authoritative state independently of the success UI."
      ],
      "test_data_and_environment": [
        "Authorized test environment; test accounts where required.",
        "Unique records and documented expected outcomes for each workflow."
      ],
      "required_evidence": [
        "Task-to-requirement mapping, exact steps and build/environment.",
        "Request/result or exported artifact and independent state readback; disclosed mock boundaries."
      ],
      "pass_conditions": [
        "Every sampled core result matches its agreed outcome and disclosed operating mode."
      ],
      "fail_conditions": [
        "A core task reports completion but performs no required operation, or silently uses a mock."
      ],
      "unknown_when": [
        "Core task expectations, execution access or authoritative results are unavailable."
      ],
      "severity_guidance": {
        "blocker": "A required core outcome cannot be achieved.",
        "important": "A supported workflow fails with a viable workaround.",
        "improvement": "A measured secondary friction remains without violating a core outcome."
      },
      "decision_rules": {
        "fix": "Apply the smallest authorized, proportionate correction to a demonstrated violation of F01; record a measurable recheck.",
        "propose": "Use when a verified benefit needs a scope, product, architecture, access, or cost decision; retain the observed severity.",
        "preserve": "Use when current behavior meets the contract, or the suggestion is only preference with no demonstrated benefit.",
        "investigate": "Use when required observations, authorization, applicability facts, or the expected contract are missing."
      },
      "verification": [
        "Repeat the original task and verify independent readback; exercise a neighboring task for regression."
      ],
      "do_not_change": [
        "Do not invent features or replace a disclosed demo with an unrequested backend."
      ],
      "sources": [
